script:
test('inclusive end date visit is covered and leaves one visit', function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: '2026-02-01',
    endDate: '2026-04-30',
    visitDate: '2026-04-30'
  }), { covered: true, remaining: 1 });
});

test('visit one day after the end date is not covered and leaves two visits', function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: '2026-02-01',
    endDate: '2026-04-30',
    visitDate: '2026-05-01'
  }), { covered: false, remaining: 2 });
});

test('visit is not covered when used visits equal approved visits and leaves zero', function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 6,
    startDate: '2026-02-01',
    endDate: '2026-04-30',
    visitDate: '2026-03-15'
  }), { covered: false, remaining: 0 });
});

test('inclusive start date visit is covered and leaves one visit', function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: '2026-02-01',
    endDate: '2026-04-30',
    visitDate: '2026-02-01'
  }), { covered: true, remaining: 1 });
});

test('visit one day before the start date is not covered and leaves two visits', function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: '2026-02-01',
    endDate: '2026-04-30',
    visitDate: '2026-01-31'
  }), { covered: false, remaining: 2 });
});

test('visit one day after the start date is covered and leaves one visit', function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: '2026-02-01',
    endDate: '2026-04-30',
    visitDate: '2026-02-02'
  }), { covered: true, remaining: 1 });
});

test('visit one day before the end date is covered and leaves one visit', function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 4,
    startDate: '2026-02-01',
    endDate: '2026-04-30',
    visitDate: '2026-04-29'
  }), { covered: true, remaining: 1 });
});

test('last remaining visit in the middle of the range is covered and leaves zero', function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 6,
    usedVisits: 5,
    startDate: '2026-02-01',
    endDate: '2026-04-30',
    visitDate: '2026-03-15'
  }), { covered: true, remaining: 0 });
});

test('zero approved and zero used visit is not covered and leaves zero', function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 0,
    usedVisits: 0,
    startDate: '2026-02-01',
    endDate: '2026-04-30',
    visitDate: '2026-03-15'
  }), { covered: false, remaining: 0 });
});

test('one approved and zero used visit is covered and leaves zero', function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 1,
    usedVisits: 0,
    startDate: '2026-02-01',
    endDate: '2026-04-30',
    visitDate: '2026-03-15'
  }), { covered: true, remaining: 0 });
});

test('last day of December as an inclusive start is covered and leaves two visits', function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 4,
    usedVisits: 1,
    startDate: '2025-12-31',
    endDate: '2026-01-31',
    visitDate: '2025-12-31'
  }), { covered: true, remaining: 2 });
});

test('first of January inside a December start range is covered and leaves two visits', function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 4,
    usedVisits: 1,
    startDate: '2025-12-31',
    endDate: '2026-01-31',
    visitDate: '2026-01-01'
  }), { covered: true, remaining: 2 });
});

test('leap day as a single day window is covered and leaves one visit', function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 2,
    usedVisits: 0,
    startDate: '2024-02-29',
    endDate: '2024-02-29',
    visitDate: '2024-02-29'
  }), { covered: true, remaining: 1 });
});

test('visit one day before a leap day start is not covered and leaves two visits', function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 2,
    usedVisits: 0,
    startDate: '2024-02-29',
    endDate: '2024-02-29',
    visitDate: '2024-02-28'
  }), { covered: false, remaining: 2 });
});

test('visit one day after a leap day end is not covered and leaves two visits', function () {
  assert.deepEqual(code.checkAuthorization({
    approvedVisits: 2,
    usedVisits: 0,
    startDate: '2024-02-29',
    endDate: '2024-02-29',
    visitDate: '2024-03-01'
  }), { covered: false, remaining: 2 });
});

test('unknown field notes throws an error naming that field', function () {
  assert.throws(function () {
    code.checkAuthorization({
      approvedVisits: 6,
      usedVisits: 4,
      startDate: '2026-02-01',
      endDate: '2026-04-30',
      visitDate: '2026-03-15',
      notes: 'x'
    });
  }, /unknown field: notes/);
});
